use std::fs
use std::collections::HashMap

fn bal(m: HashMap<string, int>, name: string) -> Option<int> {
    m.get(name).cloned()
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut m: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" && parts.len() >= 3 {
            let name = parts[1]
            let amt = parts[2].parse::<int>().unwrap_or(-1)
            if amt < 0 {
                println("error: invalid amount")
            } else if m.contains_key(name) {
                println("error: duplicate account")
            } else {
                m.insert(name, amt)
                println("ok")
            }
        } else if cmd == "balance" && parts.len() >= 2 {
            match bal(m, parts[1]) {
                Some(b) => println("${b}"),
                None => println("error: unknown account ${parts[1]}"),
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let name = parts[1]
            let amt = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                match bal(m, name) {
                    None => println("error: unknown account ${name}"),
                    Some(b) => {
                        if cmd == "deposit" {
                            m.insert(name, b + amt)
                            println("ok")
                        } else if b < amt {
                            println("error: insufficient funds")
                        } else {
                            m.insert(name, b - amt)
                            println("ok")
                        }
                    }
                }
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let from = parts[1]
            let to = parts[2]
            let amt = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                match bal(m, from) {
                    None => println("error: unknown account ${from}"),
                    Some(fb) => {
                        match bal(m, to) {
                            None => println("error: unknown account ${to}"),
                            Some(tb) => {
                                if from == to {
                                    println("error: same account")
                                } else if fb < amt {
                                    println("error: insufficient funds")
                                } else {
                                    m.insert(from, fb - amt)
                                    m.insert(to, tb + amt)
                                    println("ok")
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    let mut keys: Vec<string> = m.keys().collect()
    keys.sort()
    for k in keys {
        match bal(m, k) {
            Some(b) => println("${k} ${b}"),
            None => {},
        }
    }
}

